package com.unicarona.privacy;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.unicarona.privacy.recovery.PitrEncryptedArchive;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class PitrEncryptedArchiveTest {
    @TempDir Path temporary;private Path root,data,wal,base;private PitrEncryptedArchive archive;private Map<String,byte[]> keys;private final Instant at=Instant.parse("2026-10-26T12:00:00Z");
    private static final String WAL="000000010000000000000001",OTHER="000000010000000000000002",TARGET="unicarona-01234567-89ab-4cde-8123-456789abcdef";
    @BeforeEach void setup()throws Exception {
        Files.createDirectories(temporary.resolve("ops/retention"));root=Files.createDirectories(temporary.resolve("ops/archives/"+UUID.randomUUID()));data=Files.createDirectories(temporary.resolve("source"));Files.createDirectory(data.resolve("pg_wal"));wal=data.resolve("pg_wal/"+WAL);
        byte[] bytes=new byte[4096];ByteBuffer.wrap(bytes).order(ByteOrder.nativeOrder()).putShort(2,(short)2).putLong(24,123456L);System.arraycopy("Synthetic private marker".getBytes(),0,bytes,100,24);Files.write(wal,bytes);
        keys=Map.of("rehearsal",new byte[32]);archive=new PitrEncryptedArchive(root,keys,Clock.fixed(at,ZoneOffset.UTC));archive.initialize(UUID.randomUUID(),"123456",at,at.plus(Duration.ofDays(35)),"rehearsal");
        base=Files.createDirectory(temporary.resolve("base"));Files.writeString(base.resolve("backup_label"),"Synthetic physical base");Files.writeString(base.resolve("backup_manifest"),"{\"System-Identifier\":123456}");Files.createDirectory(base.resolve("base"));Files.writeString(base.resolve("base/data"),"Synthetic protected database bytes");
    }
    private void complete()throws Exception{archive.archiveWal(data,wal,WAL);archive.sealBase(base);archive.finish(TARGET,"0/1000100",WAL);}
    private Path target()throws Exception{Path target=Files.createDirectory(temporary.resolve("restored"));Files.createDirectory(target.resolve("pg_wal"));return target;}
    @Test void ciphertextRoundTripsWithoutPlaintextObjectFiles()throws Exception{complete();Path destination=target();archive.fetchWal(destination,Path.of("pg_wal/RECOVERYXLOG"),WAL);assertArrayEquals(Files.readAllBytes(wal),Files.readAllBytes(destination.resolve("pg_wal/RECOVERYXLOG")));assertFalse(new String(Files.readAllBytes(root.resolve(WAL+".gcm")),java.nio.charset.StandardCharsets.ISO_8859_1).contains("Synthetic private marker"));Path restored=temporary.resolve("base-restored");archive.restoreBase(restored);assertEquals("Synthetic protected database bytes",Files.readString(restored.resolve("base/data")));}
    @Test void repeatArchiveIsIdempotentAndConflictingBytesCannotOverwriteIt()throws Exception{archive.archiveWal(data,wal,WAL);byte[] original=Files.readAllBytes(root.resolve(WAL+".gcm"));archive.archiveWal(data,wal,WAL);assertArrayEquals(original,Files.readAllBytes(root.resolve(WAL+".gcm")));byte[] changed=Files.readAllBytes(wal);changed[500]=3;Files.write(wal,changed);assertThrows(IOException.class,()->archive.archiveWal(data,wal,WAL));assertArrayEquals(original,Files.readAllBytes(root.resolve(WAL+".gcm")));}
    @Test void authenticationFailureCannotPublishPartialPlaintextOverAPostgresTarget()throws Exception{complete();Path target=target();Path destination=target.resolve("pg_wal/RECOVERYXLOG");Files.writeString(destination,"Original recovery target");Path object=root.resolve(WAL+".gcm");byte[] changed=Files.readAllBytes(object);changed[changed.length-1]^=1;Files.write(object,changed);assertThrows(IOException.class,()->archive.fetchWal(target,destination,WAL));assertEquals("Original recovery target",Files.readString(destination));try(var files=Files.list(target.resolve("pg_wal"))){assertEquals(1,files.count());}}
    @Test void wrongKeyAndRenamedObjectsFailAuthentication()throws Exception{complete();byte[] bad=new byte[32];Arrays.fill(bad,(byte)1);assertThrows(IOException.class,()->new PitrEncryptedArchive(root,Map.of("rehearsal",bad),Clock.fixed(at,ZoneOffset.UTC)).index());Files.copy(root.resolve(WAL+".gcm"),root.resolve(OTHER+".gcm"));Path target=target();assertThrows(IOException.class,()->archive.fetchWal(target,Path.of("pg_wal/RECOVERYXLOG"),OTHER));assertFalse(Files.exists(target.resolve("pg_wal/RECOVERYXLOG")));}
    @Test void signedIndexCannotExtendRetentionOrAcceptUnknownFields()throws Exception{var json=new ObjectMapper();Path index=root.resolve("index.json");String original=Files.readString(index);var value=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(original);value.put("expires",at.plus(Duration.ofDays(40)).toEpochMilli());Files.writeString(index,value.toString());assertThrows(IOException.class,archive::index);value=(com.fasterxml.jackson.databind.node.ObjectNode)json.readTree(original);value.put("unknown",true);Files.writeString(index,value.toString());assertThrows(IOException.class,archive::index);}
    @Test void expiredBundleCannotBeUsedEvenIfCleanupHasNotRemovedIt()throws Exception{complete();var expired=new PitrEncryptedArchive(root,keys,Clock.fixed(at.plus(Duration.ofDays(36)),ZoneOffset.UTC));assertThrows(IOException.class,expired::index);Path target=target();assertThrows(IOException.class,()->expired.fetchWal(target,Path.of("pg_wal/RECOVERYXLOG"),WAL));assertTrue(Files.exists(root.resolve(WAL+".gcm")));}
    @Test void sourceAndRestorePathsCannotEscapeTheirConfiguredCluster()throws Exception{Path outside=temporary.resolve(WAL);Files.copy(wal,outside);assertThrows(IOException.class,()->archive.archiveWal(data,outside,WAL));assertThrows(IOException.class,()->archive.archiveWal(data,wal,"../outside"));complete();Path target=target();assertThrows(IOException.class,()->archive.fetchWal(target,temporary.resolve("outside-target"),WAL));assertFalse(Files.exists(temporary.resolve("outside-target")));}
    @Test void foreignClusterWalCannotBeAccepted()throws Exception{byte[] wrong=Files.readAllBytes(wal);ByteBuffer.wrap(wrong).order(ByteOrder.nativeOrder()).putLong(24,9999L);Files.write(wal,wrong);assertThrows(IOException.class,()->archive.archiveWal(data,wal,WAL));assertFalse(Files.exists(root.resolve(WAL+".gcm")));}
    @Test void activeDataDirectoryCannotBeSealedAsAPhysicalBase()throws Exception{Files.writeString(base.resolve("postmaster.pid"),"Synthetic active cluster marker");assertThrows(IOException.class,()->archive.sealBase(base));assertFalse(Files.exists(root.resolve("base.zip.gcm")));}
    @Test void targetIsImmutableAndFinishingAgainReverifiesItsObjects()throws Exception{complete();long expires=archive.index().expires();archive.finish(TARGET,"0/1000100",WAL);assertEquals(expires,archive.index().expires());assertThrows(IOException.class,()->archive.finish("unicarona-"+UUID.randomUUID(),"0/1000100",WAL));assertThrows(IOException.class,()->archive.archiveWal(data,wal,WAL));Files.delete(root.resolve(WAL+".gcm"));assertThrows(IOException.class,()->archive.finish(TARGET,"0/1000100",WAL));}
    @Test void baseRestoreNeverOverwritesAnExistingDataDirectory()throws Exception{complete();Path existing=Files.createDirectory(temporary.resolve("existing"));Files.writeString(existing.resolve("sentinel"),"Preserve this cluster");assertThrows(IOException.class,()->archive.restoreBase(existing));assertEquals("Preserve this cluster",Files.readString(existing.resolve("sentinel")));}
    @Test void corruptBaseDoesNotLeaveAnExtractedDatabase()throws Exception{complete();Path object=root.resolve("base.zip.gcm");byte[] changed=Files.readAllBytes(object);changed[changed.length-2]^=1;Files.write(object,changed);Path target=temporary.resolve("bad-base");assertThrows(IOException.class,()->archive.restoreBase(target));assertFalse(Files.exists(target));try(var listing=Files.list(temporary)){assertTrue(listing.noneMatch(p->p.getFileName().toString().startsWith("pitr-restore-")));}}
}
